function formTemporal(){
 if($('#advancedEnabled').checked)return advancedTemporal();
 const s=system(),qualifier=$('#'+(s.type==='numeric'?'uQualifier':'certainty')).value;
 const endpoint=(prefix)=>{let value;if(s.type==='numeric'){const text=$('#'+(prefix==='start'?'uStart':'uEnd')).value;if(text==='')return null;value=Number(text);}else{value={};for(const key of ['year','month','day']){const text=$('#'+prefix+key[0].toUpperCase()+key.slice(1)).value;if(text!=='')value[key]=Number(text);}if(!Object.keys(value).length)return null;}return {value,precision:T.precision(value,s),qualifier:qualifier==='about'?'approximate':qualifier==='uncertain'?'uncertain':'exact',...(s.type==='numeric'&&$('#uUnit').value?{unit:$('#uUnit').value}:{})};};
 const start=endpoint('start'),end=s.type==='numeric'||$('#dateKind').value==='range'?endpoint('end'):null;
 if(qualifier==='before')return {kind:'openInterval',start:null,end:start};if(qualifier==='after')return {kind:'openInterval',start,end:null};return {kind:$('#dateKind').value==='range'&&s.type==='gregorian'||end?'interval':'point',start,end};
}
function saveEvent(){
 if(App.fileReads){toast('Lecture des fichiers en cours.');return;}
 const title=$('#eventTitle').value.trim();if(!title){$('#eventTitle').focus();toast('Ajoute un titre.');return;}
 const t=currentTimeline(),old=t.events.find(e=>e.id===App.editingId);let temporal;
 try{temporal=formTemporal();T.validateTemporal(temporal,system());C.validateLinks($('#eventLinks').value.trim());if(!temporal.start&&!temporal.end&&!$('#dateLabel').value.trim())throw new Error('Indique un repère ou un libellé temporel.');
 // Une édition textuelle ne détruit ni horaire ni temporalité avancée.
 if(old){const stripped=P.clone(old.temporal);for(const ep of [stripped.start,stripped.end])if(ep){for(const key of ['hour','minute','second','tzid','utc'])delete ep.value?.[key];delete ep.notBefore;delete ep.notAfter;ep.precision=T.precision(ep.value,system());}if(JSON.stringify(stripped)===JSON.stringify(temporal))temporal=P.clone(old.temporal);}
 }catch(error){toast(error.message);return;}
 const eid=old?.id||P.id(),selected=$$('#relationList input:checked').map(el=>el.value);
 const ok=commit((draft,assets)=>{
  const timeline=draft.timelines.find(x=>x.id===t.id),e=old?timeline.events.find(x=>x.id===eid):P.event(title,temporal);e.id=eid;
  Object.assign(e,{title,type:$('#eventKind').value||old?.type||'Événement',temporal,summary:$('#eventSummary').value.trim(),markdown:$('#eventMarkdown').value.trim(),links:$('#eventLinks').value.trim(),displayDate:$('#dateLabel').value.trim(),color:$('#eventColor').value,tags:$('#eventTags').value.split(',').map(v=>v.trim()).filter(Boolean),place:$('#eventLocation').value.trim(),updatedAt:P.stamp()});
  const group=$('#eventGroup').value.trim();let lane=timeline.lanes.find(l=>l.name===group);if(group&&!lane){lane={id:P.id(),name:group,order:timeline.lanes.length,visible:true,color:e.color,description:''};timeline.lanes.push(lane);}e.laneId=lane?.id||null;
  const sources=$('#eventSources').value.trim();if(!old||sources!==sourceText(old)){let source=draft.sources.find(s=>s.type==='note'&&s.citation===sources);if(sources&&!source){source={id:P.id(),title:sources.split('\n')[0].slice(0,140),type:'note',citation:sources};draft.sources.push(source);}e.sourceIds=source?[source.id]:[];}
  e.mediaIds=App.pendingMedia.map((row,i)=>{row.media.alt=$(`[data-media-alt="${i}"]`)?.value||row.media.alt||'';row.media.caption=$(`[data-media-caption="${i}"]`)?.value||row.media.caption||'';const index=draft.media.findIndex(m=>m.id===row.media.id);if(index>=0)draft.media[index]=P.clone(row.media);else draft.media.push(P.clone(row.media));if(row.blob)assets.set(row.media.storageRef,row.blob);return row.media.id;});
  if(!old)timeline.events.push(e);const shown=new Set($$('#relationList input').map(el=>el.value)),wanted=new Set(selected);timeline.relations=timeline.relations.filter(r=>{if(r.type!=='related'||r.direction!=='undirected'||r.sourceId!==eid&&r.targetId!==eid)return true;const other=r.sourceId===eid?r.targetId:r.sourceId;return !shown.has(other)||wanted.has(other);});for(const targetId of selected)if(!timeline.relations.some(r=>r.type==='related'&&r.direction==='undirected'&&(r.sourceId===eid&&r.targetId===targetId||r.sourceId===targetId&&r.targetId===eid)))timeline.relations.push({id:P.id(),sourceId:eid,targetId,type:'related',direction:'undirected',note:''});
 },old?'Événement mis à jour.':'Événement ajouté.');if(ok){closeEditor();render();$('#addEventBtn').focus();}
}
