function fillAdvanced(e){const s=system(),t=e?.temporal||{kind:'point',start:null,end:null};$('#advancedEnabled').checked=s.type==='customCalendar'||[t.start,t.end].filter(Boolean).some(ep=>ep.notBefore!==undefined||ep.notAfter!==undefined||ep.value.hour!==undefined||ep.value.era)||!!(t.start&&t.end&&t.start.qualifier!==t.end.qualifier);$('#advancedTime').open=$('#advancedEnabled').checked;$('#advancedKind').value=t.kind;$('#advancedHelp').textContent=s.type==='numeric'?'Valeur décimale dans la direction de cet axe.':s.type==='customCalendar'?'Année-mois-jour, avec @NomÈre facultatif. Mois : '+s.definition.months.map((m,i)=>(i+1)+' '+m.name).join(', '):'Année seule ou ISO : 1998-03, 2012-07-09T12:30Z, ou [Europe/Paris]. Une case vide reste inconnue.';for(const [prefix,ep]of [['a',t.start],['b',t.end]]){for(const [suffix,key]of [['Value','value'],['Before','notBefore'],['After','notAfter']])$('#'+prefix+suffix).value=ep?.[key]!==undefined?T.valueText(ep[key],s):'';$('#'+prefix+'Qualifier').value=ep?.qualifier||'exact';}}
function advancedTemporal(){const s=system(),endpoint=prefix=>{const value=T.parseValue($('#'+prefix+'Value').value,s);if(value===null)return null;const ep={value,precision:T.precision(value,s),qualifier:$('#'+prefix+'Qualifier').value};for(const [suffix,key]of [['Before','notBefore'],['After','notAfter']]){const bound=T.parseValue($('#'+prefix+suffix).value,s);if(bound!==null)ep[key]=bound;}return ep;};return {kind:$('#advancedKind').value,start:endpoint('a'),end:endpoint('b')};}
function fillSystemDefinition(s){const d=s.definition;$('#definitionOverride').checked=false;$('#timelineUnitField').classList.toggle('hidden',s.type!=='numeric');$('#numericDefinitionFields').classList.toggle('hidden',s.type!=='numeric');$('#calendarDefinitionFields').classList.toggle('hidden',s.type!=='customCalendar');$('#systemDirection').value=d.direction||1;$('#calendarMonths').value=(d.months||[]).map(m=>m.name+' | '+m.days).join('\n');$('#calendarIntercalary').value=d.intercalaryDays||0;$('#calendarEras').value=(d.eras||[]).map(e=>e.name+' | '+e.offset).join('\n');$('#calendarHigher').value=(d.higherUnits||[]).filter(x=>typeof x==='string').join(', ');$('#calendarFormat').value=d.displayFormat||'jour mois année ère';}
function readSystemDefinition(type,previous){if(type==='numeric')return {...previous,unit:$('#timelineUnit').value.trim()||'cycle',direction:Number($('#systemDirection').value)};const rows=(value,key)=>value.split('\n').filter(x=>x.trim()).map(line=>{const parts=line.split('|');if(parts.length!==2||!parts[0].trim()||!parts[1].trim())throw Error('Chaque ligne doit contenir nom | nombre.');return {name:parts[0].trim(),[key]:Number(parts[1])};});return {...previous,months:rows($('#calendarMonths').value,'days'),intercalaryDays:Number($('#calendarIntercalary').value),eras:rows($('#calendarEras').value,'offset'),higherUnits:$('#calendarHigher').value.split(',').map(x=>x.trim()).filter(Boolean),displayFormat:$('#calendarFormat').value};}
