function openSpan(id=null){const t=currentTimeline(),s=t.spans.find(x=>x.id===id);App.editingSpanId=id;$('#spanTitle').value=s?.title||'';$('#spanStart').value=s?.temporal.start?T.valueText(s.temporal.start.value,system()):'';$('#spanEnd').value=s?.temporal.end?T.valueText(s.temporal.end.value,system()):'';$('#spanColor').value=s?.color||'#cadbc8';$('#spanLane').innerHTML='<option value="">Tous les fils</option>'+t.lanes.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');$('#spanLane').value=s?.laneId||'';$('#deleteSpanBtn').classList.toggle('hidden',!s);$('#spanDialog').showModal();}
function saveSpan(){try{const endpoint=text=>{const value=T.parseValue(text,system());return value===null?null:{value,precision:T.precision(value,system()),qualifier:'exact'}},start=endpoint($('#spanStart').value),end=endpoint($('#spanEnd').value),previous=currentTimeline().spans.find(s=>s.id===App.editingSpanId);let temporal={kind:start&&end?'interval':'openInterval',start,end};if(previous){const old=previous.temporal,same=$('#spanStart').value.trim()===(old.start?T.valueText(old.start.value,system()):'')&&$('#spanEnd').value.trim()===(old.end?T.valueText(old.end.value,system()):'');if(same)temporal=P.clone(old);else if([old.start,old.end].filter(Boolean).some(ep=>ep.qualifier!=='exact'||ep.notBefore!==undefined||ep.notAfter!==undefined)&&!confirm('Modifier ces dates remet leurs qualifications et possibilités à des bornes connues. Continuer ?'))return;}T.validateTemporal(temporal,system());if(commit(p=>{const t=p.timelines.find(t=>t.id===App.currentId),old=t.spans.find(s=>s.id===App.editingSpanId);const value={id:old?.id||P.id(),title:$('#spanTitle').value.trim(),temporal,laneId:$('#spanLane').value||null,color:$('#spanColor').value};if(old)Object.assign(old,value);else t.spans.push(value);},'Période de fond enregistrée.')){$('#spanDialog').close();renderSpanRows();$('#spansDefinition').value=JSON.stringify(currentTimeline().spans,null,2);}}catch(error){toast(error.message);}}
