function legacyTimeline(t=currentTimeline()){
 const s=system(t);if(s.type==='customCalendar')throw new Error('Ce format ne porte pas un calendrier personnalisé.');
 const q=value=>value==='approximate'?'about':value||'exact';
 const result={id:t.id,name:t.title,timeMode:s.type==='numeric'?'universal':'calendar',unit:s.definition.unit||'cycle',events:t.events.filter(e=>{const ep=[e.temporal.start,e.temporal.end].filter(Boolean);return !ep.some(a=>a.notBefore!==undefined||a.notAfter!==undefined)&&!(ep.length===2&&ep[0].qualifier!==ep[1].qualifier);}).map(e=>{
  const a=e.temporal.start||e.temporal.end,b=e.temporal.kind==='interval'?e.temporal.end:null;let time={};const qualifier=e.temporal.kind==='openInterval'?(e.temporal.start?'after':'before'):q(a?.qualifier);
  if(s.type==='numeric')time={start:a?.value??'',end:b?.value??'',unit:a?.unit||s.definition.unit,qualifier};else{time={kind:b?'range':'point',certainty:qualifier};for(const [prefix,ep]of [['start',a],['end',b]])for(const key of ['year','month','day'])time[prefix+key[0].toUpperCase()+key.slice(1)]=ep?.value[key]??'';if(a?.value.hour!==undefined)time.ical={start:T.icsEndpoint(a.value),...(b?.value.hour!==undefined?{end:T.icsEndpoint(b.value)}:{})};}
  return {id:e.id,title:e.title,kind:e.type,color:e.color,dateLabel:e.displayDate,summary:e.summary,markdown:e.markdown,group:eventLane(e,t),tags:e.tags,location:e.place,sources:sourceText(e),links:e.links,time,attachments:[],relations:t.relations.filter(r=>r.type==='related'&&r.direction==='undirected'&&(r.sourceId===e.id||r.targetId===e.id)).map(r=>r.sourceId===e.id?r.targetId:r.sourceId),externalIds:e.externalIds,icalRelations:e.metadata?.icalRelations||[]};})};const included=new Set(result.events.map(e=>e.id));for(const e of result.events)e.relations=e.relations.filter(id=>included.has(id));return result;
}
