function reportMarkdown(events=null,title=null){const options=publicationOptions();events=events||publicationEvents(options);title=title||options.title;const has=key=>options.fields.split(',').includes(key);return '# '+title+'\n\n'+(options.subtitle?options.subtitle+'\n\n':'')+events.map(e=>'## '+e.title+'\n\n'+[has('date')?'**'+eventLabel(e)+'**':'',has('summary')?e.summary:'',has('markdown')?e.markdown:'',has('place')&&e.place?'Lieu : '+e.place:'',has('lane')&&options.lanes&&eventLane(e)?'Fil : '+eventLane(e):'',has('tags')&&e.tags.length?'Tags : '+e.tags.join(', '):'',options.sources&&sourceText(e)?'Sources :\n'+sourceText(e):'',has('links')?parsedLinks(e.links).map(l=>'- ['+l.label+']('+l.url+')').join('\n'):'',has('relations')?relationText(e):'',has('media')?eventMedia(e).map(m=>'- Fichier : '+m.name+(m.caption?' — '+m.caption:'')).join('\n'):''].filter(Boolean).join('\n\n')).join('\n\n');}
