function relationText(e,t=currentTimeline()){return t.relations.filter(r=>r.sourceId===e.id||r.targetId===e.id).map(r=>{const other=t.events.find(x=>x.id===(r.sourceId===e.id?r.targetId:r.sourceId));return (r.direction==='directed'?(r.sourceId===e.id?'→ ':'← '):'↔ ')+r.type+' : '+(other?.title||'')+(r.note?' — '+r.note:'');}).join('\n');}
