function publicationOptions(){const margin=Number($('#pubMargin').value);if(!Number.isFinite(margin)||margin<0||margin>40)throw Error('Choisis des marges entre 0 et 40 mm.');const density=$('#pubDensity').value,fields=density==='compact'?'date':density==='summary'?$('#pubFields').value.split(',').filter(key=>key!=='markdown').join(','):$('#pubFields').value;return {title:$('#pubTitle').value||currentTimeline().title,subtitle:$('#pubSubtitle').value,format:$('#pubFormat').value,orientation:$('#pubOrientation').value,margin,fields,media:$('#pubMedia').checked,sources:$('#pubSources').checked,lanes:$('#pubLanes').checked,spans:$('#pubSpans').checked,legend:$('#pubLegend').checked,range:$('#pubRange').checked};}
