async function publicationReport(events,t,options){const fields=new Set(options.fields.split(',')),parts=[];for(const e of events){const media=eventMedia(e);parts.push(`<article><h2>${esc(e.title)}</h2>${fields.has('date')?`<p>${esc(eventLabel(e,t))}</p>`:''}${fields.has('summary')?`<p>${esc(e.summary)}</p>`:''}${fields.has('markdown')?markdown(e.markdown):''}${fields.has('place')?`<p>${esc(e.place)}</p>`:''}${fields.has('lane')&&options.lanes?`<p>Fil : ${esc(eventLane(e,t))}</p>`:''}${fields.has('tags')?`<p>${esc(e.tags.join(', '))}</p>`:''}${options.sources?`<pre>${esc(sourceText(e))}</pre>`:''}${fields.has('links')?parsedLinks(e.links).map(l=>`<p><a href="${esc(l.url)}">${esc(l.label)}</a></p>`).join(''):''}${fields.has('relations')?`<pre>${esc(relationText(e,t))}</pre>`:''}${fields.has('media')?media.map(m=>`<p>Fichier : ${esc(m.name)} ${esc(m.caption||'')}</p>`).join(''):''}${options.media?(await Promise.all(media.filter(m=>!m.remoteUrl&&m.mimeType.startsWith('image/')).map(async m=>`<img src="${esc(await S.dataURL(App.assets.get(m.storageRef)))}" alt="${esc(m.alt||e.title)}">`))).join(''):''}</article>`);}return '<section><h1>'+esc(options.title||t.title)+'</h1><p>'+esc(options.subtitle)+'</p>'+parts.join('')+'</section>';}
