function plainHTML(value){const text=String(value||'').replace(/<(script|style|iframe|object|embed)\b[^>]*>[\s\S]*?<\/\1\s*>/gi,'').replace(/<br\b[^>]*>|<\/(?:p|div|li|h[1-6]|blockquote)\s*>/gi,'\n').replace(/<[^>]*>/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;');return new DOMParser().parseFromString('<body>'+text+'</body>','text/html').body.textContent.trim();}
async function timelineJSImport(data){const legacy={version:2,currentId:'import-timeline',timelines:[{id:'import-timeline',name:plainHTML(data.title?.text?.headline)||'TimelineJS',timeMode:'calendar',events:[]}]};for(const item of data.events){const a=item.start_date,b=item.end_date;if(!a)throw new Error('Date TimelineJS absente.');const attachments=[];if(item.media?.url){const url=item.media.url;if(url.startsWith('data:')){const type=url.slice(5,url.indexOf(';')),payload=url.split(',')[1];attachments.push({id:P.id(),name:'Média',type,size:atob(payload).length,dataUrl:url});}else attachments.push({id:P.id(),name:'Média distant',type:'text/uri-list',size:0,remoteUrl:url});}legacy.timelines[0].events.push({id:P.id(),title:plainHTML(item.text?.headline)||'Sans titre',summary:'',markdown:plainHTML(item.text?.text),group:item.group||'',dateLabel:item.display_date||'',tags:[],relations:[],attachments,time:{kind:b?'range':'point',certainty:'exact',startYear:a.year??'',startMonth:a.month??'',startDay:a.day??'',endYear:b?.year??'',endMonth:b?.month??'',endDay:b?.day??''}});}const result=P.fromLegacy(legacy);for(const [i,e]of result.project.timelines[0].events.entries()){const item=data.events[i];for(const [key,field]of [['start','start_date'],['end','end_date']])if(e.temporal[key]&&item[field]?.hour!==undefined){for(const component of ['hour','minute','second'])if(item[field][component]!==undefined)e.temporal[key].value[component]=Number(item[field][component]);e.temporal[key].precision=T.precision(e.temporal[key].value,result.project.timeSystems[0]);}}P.validate(result.project);for(const [ref,url]of result.assets){const m=result.project.media.find(m=>m.storageRef===ref);result.assets.set(ref,S.fromDataURL(url,m.mimeType,m.size));}await S.validateAssets(result.project,result.assets);return result;}
