function confirmFidelity(format){const capabilities=D.CAPABILITIES[format];if(!capabilities)return Promise.resolve(true);$('#fidelityContent').innerHTML='<table class="table-view"><thead><tr><th>Élément</th><th>Traitement</th></tr></thead><tbody>'+Object.entries(capabilities).map(([key,value])=>`<tr><th>${esc(({temporal:'Temporalité',systems:'Systèmes temporels',media:'Médias',relations:'Relations',sources:'Sources'})[key])}</th><td>${esc(value)}</td></tr>`).join('')+'</tbody></table>';const dialog=$('#fidelityDialog');dialog.returnValue='';dialog.showModal();return new Promise(resolve=>{const button=$('#fidelityApply'),apply=()=>dialog.close('apply');button.addEventListener('click',apply);dialog.addEventListener('close',()=>{button.removeEventListener('click',apply);resolve(dialog.returnValue==='apply');},{once:true});});}
async function mapCSV(text,name){const rows=C.parseCSV(text),headers=rows[0];if(headers.includes('project_json')||headers.includes('time_mode'))return D.readCSV(text,name);const fields=[['title','Titre',['title','titre','event_name','headline','name','nom']],['start','Début / EDTF',['start_date','start','date','debut','début','edtf']],['end','Fin',['end_date','end','fin']],['summary','Résumé',['summary','description','notes','résumé']],['markdown','Texte complet',['markdown','text','texte']],['lane','Fil',['group','lane','layer_name','fil']],['tags','Tags',['tags']],['place','Lieu',['location','place','lieu']],['source','Source',['sources','source']],['id','Identifiant externe',['id','uid','event_id']]];$('#csvMappingFields').innerHTML=fields.map(([key,label,aliases])=>{const guess=headers.findIndex(h=>aliases.includes(h.trim().toLowerCase()));return `<label class="field">${esc(label)}<select data-map="${key}"><option value="">Ignorer</option>${headers.map((h,i)=>`<option value="${i}" ${i===guess?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`;}).join('');$('#csvDetected').textContent='Séparateur : '+(C.detectDelimiter(text)==='\t'?'tabulation':C.detectDelimiter(text))+' · texte décodé UTF-8 · '+(rows.length-1)+' ligne(s). Les valeurs source restent intactes avant confirmation.';let result;
 const convert=()=>{try{const mapping=Object.fromEntries($$('[data-map]').map(el=>[el.dataset.map,el.value]));mapping.mode=$('#csvMode').value;mapping.unit=$('#csvUnit').value;mapping.direction=$('#csvDirection').value;result=D.readCSV(text,name,mapping);$('#csvErrors').textContent=result.errors.slice(0,100).map(e=>'Ligne '+e.line+' : '+e.message).join('\n');$('#csvConversions').innerHTML='<table class="table-view"><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'<th>Conversion temporelle</th></tr></thead><tbody>'+rows.slice(1,7).map((row,i)=>'<tr>'+row.map(value=>'<td>'+esc(value.slice(0,160))+'</td>').join('')+'<td>'+esc(result.project.timelines[0].events[i]?T.label(result.project.timelines[0].events[i].temporal,result.project.timeSystems[0]):'voir erreurs')+'</td></tr>').join('')+'</tbody></table>';$('#csvApply').disabled=!!result.errors.length;}catch(error){result=null;$('#csvErrors').textContent=error.message;$('#csvApply').disabled=true;}};
 const dialog=$('#csvMappingDialog'),button=$('#csvApply'),apply=()=>dialog.close('apply');dialog.returnValue='';dialog.addEventListener('change',convert);button.addEventListener('click',apply);convert();dialog.showModal();return new Promise(resolve=>dialog.addEventListener('close',()=>{dialog.removeEventListener('change',convert);button.removeEventListener('click',apply);resolve(dialog.returnValue==='apply'?result:null);},{once:true}));}
function applyImport(result,destination){P.validate(result.project);if(result.errors?.length)throw Error('Corrige les erreurs avant l’import.');if(destination==='replace'){return commit((draft,assets)=>{Object.assign(draft,result.project);assets.clear();for(const [ref,blob]of result.assets)assets.set(ref,blob);},'Projet restauré.');}if(['merge','update'].includes(destination)){const merged=D.merge(App.project,App.assets,result.project,result.assets,App.currentId,destination==='update');return commit((draft,assets)=>{Object.assign(draft,merged.project);for(const [ref,blob]of merged.assets)assets.set(ref,blob);},'Fusion appliquée.');}const incoming=D.rebase(result.project,result.assets);return commit((draft,assets)=>{draft.timelines.push(...incoming.project.timelines);draft.timeSystems.push(...incoming.project.timeSystems);draft.media.push(...incoming.project.media);draft.sources.push(...incoming.project.sources);for(const [ref,blob]of incoming.assets)assets.set(ref,blob);},'Chronologies ajoutées.');}
async function importInterchange(file){try{if(file.size>S.MAX_BYTES)throw Error('256 Mo maximum par fichier.');const name=file.name.toLowerCase();let result;if(name.endsWith('.chronea'))result=await S.unpack(file);else{const text=await file.text();if(/\.(csv|tsv)$/.test(name)){result=await mapCSV(text,file.name);if(!result)return;}else if(/^\s*BEGIN:VCALENDAR/.test(text)){const parsed=C.fromICS(text,P.id,file.name);result={...P.fromLegacy({version:2,currentId:parsed.timeline.id,timelines:[parsed.timeline]}),warnings:parsed.warnings,assets:new Map()};}else{const data=JSON.parse(text);result=['Event','Group'].includes(data['@type'])?D.readJSCalendar(data):Array.isArray(data.events)?await timelineJSImport(data):await S.readJSON(data);}}P.validate(result.project);if(!await previewImport(result))return;const destination=$('#importDestination').value;if(destination==='replace'&&!confirm('Remplacer le projet actuel ? Cette action peut être annulée.'))return;if(!applyImport(result,destination))return;App.currentId=destination==='replace'?App.project.timelines[0].id:destination==='add'?App.project.timelines.at(-1).id:App.currentId;App.prefs.camera=null;App.clusterFilter=null;App.prefs.group='';App.prefs.search='';App.prefs.page=0;App.rangeCache=new WeakMap();render();if($('#exportDialog').open)$('#exportDialog').close();toast('Import validé et appliqué ; annulation disponible.');}catch(error){toast('Import refusé : '+error.message);}}
async function showRecovery(){
 const rows=await App.store.snapshots(App.blocked?(App.store.lastReadId||App.project.id):App.project.id).catch(()=>[]);if(!App.blocked&&!rows.length){toast('Aucun instantané disponible.');return;}
 $('#recoveryText').textContent=App.blocked?'Le contenu original est préservé. Aucune sauvegarde automatique ne le remplacera. Exporte le contenu brut avant de restaurer un instantané.':'Choisis un instantané à restaurer. Tu pourras annuler la restauration.';
 $('#recoverySnapshots').innerHTML=rows.map((row,i)=>`<button class="btn" data-snapshot-index="${i}">Restaurer ${esc(row.at||'la sauvegarde précédente')}</button>`).join('');
 $$('[data-snapshot-index]').forEach(button=>button.addEventListener('click',async()=>{try{const result=await App.store.restoreSnapshot(rows[Number(button.dataset.snapshotIndex)]);if(App.blocked&&!archiveRecovery())return;recordHistory();App.project=result.project;App.assets=result.assets;App.currentId=App.project.timelines[0].id;App.blocked=false;App.revision++;persist();render();$('#recoveryDialog').close();}catch(error){toast(error.message);}}));$('#exportRecovery').classList.toggle('hidden',!App.recoveryRaw);$('#newAfterRecovery').classList.toggle('hidden',!App.blocked);$('#recoveryDialog').showModal();
}
