function changeRange(){try{const s=system(),a=T.parseValue($('#rangeFrom').value,s),b=T.parseValue($('#rangeTo').value,s);if(a===null&&b===null)App.prefs.camera=null;else{const full=bounds(),min=a===null?full.min:T.valueBounds(a,s).min,max=b===null?full.max:T.valueBounds(b,s).max;if(min===null||max===null||min>=max)throw new Error('La fenêtre doit avoir un début inférieur à la fin.');App.prefs.camera={min,max};}App.prefs.page=0;savePrefs();render();}catch(error){toast(error.message);}}
