 $('#advancedEnabled').addEventListener('change',()=>{if($('#advancedEnabled').checked&&!$('#aValue').value&&!$('#bValue').value){try{$('#advancedEnabled').checked=false;const temporal=formTemporal();fillAdvanced({temporal});$('#advancedEnabled').checked=true;$('#advancedTime').open=true;}catch(error){$('#advancedEnabled').checked=true;toast(error.message);}}});

